// Missed-Call Text-Back (Lite) - MIT licence. Edit CONFIG, leave the rest.
const CONFIG = {
  businessName: 'Smith Plumbing',
  smsFrom: '+61400000001',                       // your Twilio AU mobile number
  twilioAccountSid: 'ACxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',
  twilioBaseUrl: 'https://api.twilio.com',
  dedupeHours: 12,
  message: "Hi, it's {business}. Sorry we missed your call - we're on a job. Reply with what you need and we'll get back to you. Reply STOP to opt out",
  voiceMessage: 'Sorry we missed your call. We will text you right now.',
};

const req = $input.first().json;
const body = req.body || {};
const store = $getWorkflowStaticData('global');
store.optOut = store.optOut || {};
store.lastTexted = store.lastTexted || {};
const now = Date.now();
function toE164AU(raw) {
  let s = String(raw || '').replace(/[\s\-().]/g, '');
  if (/^0[2-9]\d{8}$/.test(s)) s = '+61' + s.slice(1);
  else if (/^61[2-9]\d{8}$/.test(s)) s = '+' + s;
  return /^\+\d{8,15}$/.test(s) ? s : null;
}
const from = toE164AU(body.From || body.from);
const isMobile = /^\+614\d{8}$/.test(from || '');
const xml = inner => ({ contentType: 'text/xml', body: '<?xml version="1.0" encoding="UTF-8"?><Response>' + inner + '</Response>' });
let sms = null, response, action;

if (body.CallSid || req.webhookUrl?.endsWith('missed-call')) {
  if (isMobile && !store.optOut[from] && !(store.lastTexted[from] > now - CONFIG.dedupeHours * 3600000)) {
    sms = { to: from, body: CONFIG.message.replace('{business}', CONFIG.businessName) };
    store.lastTexted[from] = now;
    action = 'texted';
  } else action = 'skipped';
  response = xml(`<Say language="en-AU">${CONFIG.voiceMessage}</Say><Hangup/>`);
} else {
  const text = String(body.Body || body.body || '').trim();
  if (from && /^(stop|stopall|unsubscribe|cancel|end|quit)\b/i.test(text)) { store.optOut[from] = new Date().toISOString(); action = 'opted-out'; }
  else if (from && /^(start|unstop)\b/i.test(text)) { delete store.optOut[from]; action = 'opted-in'; }
  else action = 'reply-received (read it in your Twilio console or upgrade to Pro for owner alerts)';
  response = xml('');
}
if (sms) sms = { ...sms, from: CONFIG.smsFrom, accountSid: CONFIG.twilioAccountSid, baseUrl: CONFIG.twilioBaseUrl };
return [{ json: { action, from, sms, response } }];
